package api

import (
	"encoding/csv"
	"net/http"
	"time"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/store"
)

func customerKey(c store.Customer) cursor { return cursor{T: c.CreatedAt, ID: c.ID} }

// listCustomers lists the organization's customers, oldest first: all of them, those matching ?q= (name or email contains
// it, ignoring case), or the one with exactly ?email=.
func (s *Server) listCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	var cs []store.Customer
	switch {
	case q.Get("email") != "":
		cs = []store.Customer{}
		if c, ok := s.store.FindCustomerByEmail(p.OrgID, q.Get("email")); ok {
			cs = append(cs, c)
		}
	case q.Get("q") != "":
		cs = s.store.SearchCustomers(p.OrgID, q.Get("q"))
	default:
		cs = s.store.Customers(p.OrgID)
	}
	items, next := pageOf(cs, customerKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) createCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name                 string            `json:"name"`
		Email                string            `json:"email"`
		DefaultPaymentMethod string            `json:"default_payment_method"`
		Metadata             map[string]string `json:"metadata"`
	}
	if !decode(w, r, &in) {
		return
	}
	c, err := s.store.CreateCustomer(p.OrgID, in.Name, in.Email, s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	if in.DefaultPaymentMethod != "" || len(in.Metadata) > 0 {
		c, err = s.store.UpdateCustomer(p.OrgID, c.ID, func(c *store.Customer) error {
			c.DefaultPaymentMethod, c.Metadata = in.DefaultPaymentMethod, in.Metadata
			return nil
		})
		if err != nil {
			_ = s.store.DeleteCustomer(p.OrgID, c.ID)
			s.storeError(w, err)
			return
		}
	}
	s.publish(r.Context(), p.OrgID, "customer.created", c)
	writeJSON(w, http.StatusCreated, c)
}

func (s *Server) getCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	c, ok := s.store.Customer(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such customer")
		return
	}
	writeJSON(w, http.StatusOK, c)
}

func (s *Server) updateCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name                 *string            `json:"name"`
		Email                *string            `json:"email"`
		DefaultPaymentMethod *string            `json:"default_payment_method"`
		Metadata             *map[string]string `json:"metadata"`
	}
	if !decode(w, r, &in) {
		return
	}
	c, err := s.store.UpdateCustomer(p.OrgID, r.PathValue("id"), func(c *store.Customer) error {
		if in.Name != nil {
			c.Name = *in.Name
		}
		if in.Email != nil {
			c.Email = *in.Email
		}
		if in.DefaultPaymentMethod != nil {
			c.DefaultPaymentMethod = *in.DefaultPaymentMethod
		}
		if in.Metadata != nil {
			c.Metadata = *in.Metadata
		}
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "customer.updated", c)
	writeJSON(w, http.StatusOK, c)
}

func (s *Server) deleteCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	id := r.PathValue("id")
	if err := s.store.DeleteCustomer(p.OrgID, id); err != nil {
		s.storeError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "customer.deleted", map[string]string{"id": id})
	w.WriteHeader(http.StatusNoContent)
}

// exportCustomers answers the organization's customers as CSV, oldest first.
func (s *Server) exportCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	w.Header().Set("Content-Type", "text/csv; charset=utf-8")
	w.Header().Set("Content-Disposition", `attachment; filename="customers.csv"`)
	cw := csv.NewWriter(w)
	cw.UseCRLF = true
	_ = cw.Write([]string{"id", "name", "email", "created_at"})
	for _, c := range s.store.Customers(p.OrgID) {
		_ = cw.Write([]string{c.ID, c.Name, c.Email, c.CreatedAt.UTC().Format(time.RFC3339)})
	}
	cw.Flush()
}
package api

import (
	"errors"
	"fmt"
	"net/http"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// planView is a plan with its price in major units ("12.50") and formatted for people ("$12.50").
type planView struct {
	store.Plan
	Price          string `json:"price"`
	PriceFormatted string `json:"price_formatted"`
}

func viewPlan(p store.Plan) planView {
	return planView{Plan: p, Price: fmt.Sprintf("%.2f", float64(p.UnitAmount)/100), PriceFormatted: money.Format(p.UnitAmount, p.Currency)}
}

func (s *Server) listPlans(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	items := []planView{}
	for _, pl := range s.store.Plans(p.OrgID) {
		items = append(items, viewPlan(pl))
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

// createPlan takes the price in major units, as a string ("12.50"), the way people type it.
func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name      string          `json:"name"`
		Currency  money.Currency  `json:"currency"`
		Price     string          `json:"price"`
		Interval  store.Interval  `json:"interval"`
		UsageType store.UsageType `json:"usage_type"`
		TrialDays int             `json:"trial_days"`
	}
	if !decode(w, r, &in) {
		return
	}
	amount, err := money.ParseMajor(in.Price, in.Currency)
	if err != nil {
		if errors.Is(err, money.ErrInvalidAmount) {
			writeError(w, http.StatusUnprocessableEntity, "invalid_amount", err.Error())
			return
		}
		s.storeError(w, err)
		return
	}
	pl, err := s.store.CreatePlan(store.Plan{OrgID: p.OrgID, Name: in.Name, Currency: in.Currency, UnitAmount: amount, Interval: in.Interval,
		UsageType: in.UsageType, TrialDays: in.TrialDays}, s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, viewPlan(pl))
}

func (s *Server) getPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pl, ok := s.store.Plan(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such plan")
		return
	}
	writeJSON(w, http.StatusOK, viewPlan(pl))
}

func (s *Server) updatePlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name   *string `json:"name"`
		Active *bool   `json:"active"`
	}
	if !decode(w, r, &in) {
		return
	}
	pl, err := s.store.UpdatePlan(p.OrgID, r.PathValue("id"), func(pl *store.Plan) error {
		if in.Name != nil {
			pl.Name = *in.Name
		}
		if in.Active != nil {
			pl.Active = *in.Active
		}
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, viewPlan(pl))
}
package api

import (
	"errors"
	"net/http"
	"time"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

func subKey(s store.Subscription) cursor { return cursor{T: s.CreatedAt, ID: s.ID} }

func (s *Server) subError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, subscriptions.ErrPlanInactive):
		writeError(w, http.StatusUnprocessableEntity, "plan_inactive", err.Error())
	case errors.Is(err, subscriptions.ErrCanceled):
		writeError(w, http.StatusConflict, "subscription_canceled", err.Error())
	default:
		s.payError(w, err)
	}
}

func (s *Server) listSubscriptions(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	subs := s.store.Subscriptions(p.OrgID, store.SubscriptionFilter{CustomerID: q.Get("customer_id"), Status: store.SubStatus(q.Get("status"))})
	items, next := pageOf(subs, subKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) createSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		CustomerID      string `json:"customer_id"`
		PlanID          string `json:"plan_id"`
		Quantity        int    `json:"quantity"`
		DiscountPercent int    `json:"discount_percent"`
	}
	if !decode(w, r, &in) {
		return
	}
	sub, err := s.subs.Create(r.Context(), p.OrgID, subscriptions.CreateInput{CustomerID: in.CustomerID, PlanID: in.PlanID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent})
	if err != nil && sub.ID == "" {
		s.subError(w, err)
		return
	}
	if err != nil {
		s.log.Error("first invoice", "subscription", sub.ID, "err", err)
	}
	writeJSON(w, http.StatusCreated, sub)
}

func (s *Server) getSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	sub, ok := s.store.Subscription(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such subscription")
		return
	}
	writeJSON(w, http.StatusOK, sub)
}

func (s *Server) updateSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		PlanID   *string `json:"plan_id"`
		Quantity *int    `json:"quantity"`
	}
	if !decode(w, r, &in) {
		return
	}
	sub, err := s.subs.Update(r.Context(), p.OrgID, r.PathValue("id"), subscriptions.UpdateInput{PlanID: in.PlanID, Quantity: in.Quantity})
	if err != nil {
		s.subError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, sub)
}

func (s *Server) cancelSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		AtPeriodEnd bool `json:"at_period_end"`
	}
	if r.ContentLength != 0 && !decode(w, r, &in) {
		return
	}
	sub, err := s.subs.Cancel(r.Context(), p.OrgID, r.PathValue("id"), in.AtPeriodEnd)
	if err != nil {
		s.subError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, sub)
}

// reportUsage records usage of a metered subscription: {"quantity": n, "timestamp": RFC 3339 (default now)}.
func (s *Server) reportUsage(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Quantity  int64      `json:"quantity"`
		Timestamp *time.Time `json:"timestamp"`
	}
	if !decode(w, r, &in) {
		return
	}
	now := s.clock.Now()
	at := now
	if in.Timestamp != nil {
		at = *in.Timestamp
	}
	u, err := s.store.AddUsage(p.OrgID, r.PathValue("id"), in.Quantity, at, now)
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, u)
}
package api

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/url"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/mail"
	"example.com/tally/internal/store"
)

func (s *Server) getMe(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	u, _ := s.store.User(p.UserID)
	o, _ := s.store.Org(p.OrgID)
	writeJSON(w, http.StatusOK, map[string]any{"user": u, "org": o, "role": p.Role, "api_key_id": p.KeyID})
}

func (s *Server) getOrg(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	o, ok := s.store.Org(p.OrgID)
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such organization")
		return
	}
	writeJSON(w, http.StatusOK, o)
}

func (s *Server) updateOrg(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	if !auth.CanManageTeam(p.Role) {
		writeError(w, http.StatusForbidden, "forbidden", "only owners and admins change the organization")
		return
	}
	var in struct {
		Name      *string        `json:"name"`
		TimeZone  *string        `json:"time_zone"`
		TaxRateBP *int           `json:"tax_rate_bp"`
		Plan      *store.OrgPlan `json:"plan"`
	}
	if !decode(w, r, &in) {
		return
	}
	o, err := s.store.UpdateOrg(p.OrgID, func(o *store.Org) error {
		if in.Name != nil {
			o.Name = *in.Name
		}
		if in.TimeZone != nil {
			o.TimeZone = *in.TimeZone
		}
		if in.TaxRateBP != nil {
			o.TaxRateBP = *in.TaxRateBP
		}
		if in.Plan != nil {
			o.Plan = *in.Plan
		}
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, o)
}

// memberView is a member with the user's details.
type memberView struct {
	UserID   string     `json:"user_id"`
	Email    string     `json:"email"`
	Name     string     `json:"name"`
	Role     store.Role `json:"role"`
	JoinedAt string     `json:"joined_at"`
}

func (s *Server) memberView(m store.Member) memberView {
	u, _ := s.store.User(m.UserID)
	return memberView{UserID: m.UserID, Email: u.Email, Name: u.Name, Role: m.Role, JoinedAt: m.CreatedAt.Format("2006-01-02T15:04:05Z07:00")}
}

func (s *Server) listMembers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	items := []memberView{}
	for _, m := range s.store.Members(p.OrgID) {
		items = append(items, s.memberView(m))
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

func (s *Server) updateMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	if !auth.CanManageTeam(p.Role) {
		writeError(w, http.StatusForbidden, "forbidden", "only owners and admins manage members")
		return
	}
	var in struct {
		Role store.Role `json:"role"`
	}
	if !decode(w, r, &in) {
		return
	}
	m, err := s.store.SetMemberRole(p.OrgID, r.PathValue("user_id"), in.Role)
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, s.memberView(m))
}

func (s *Server) removeMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	if !auth.CanManageTeam(p.Role) {
		writeError(w, http.StatusForbidden, "forbidden", "only owners and admins manage members")
		return
	}
	if err := s.store.RemoveMember(p.OrgID, r.PathValue("user_id")); err != nil {
		s.storeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) listInvites(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	writeJSON(w, http.StatusOK, list{Items: s.store.Invites(p.OrgID)})
}

func (s *Server) createInvite(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	if !auth.CanManageTeam(p.Role) {
		writeError(w, http.StatusForbidden, "forbidden", "only owners and admins invite members")
		return
	}
	var in struct {
		Email string     `json:"email"`
		Role  store.Role `json:"role"`
	}
	if !decode(w, r, &in) {
		return
	}
	inv, err := s.store.CreateInvite(p.OrgID, in.Email, in.Role, p.UserID, s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	if err := s.sendInvite(r.Context(), inv); err != nil {
		s.log.Error("send invite", "invite", inv.ID, "err", err)
	}
	writeJSON(w, http.StatusCreated, inv)
}

// sendInvite emails the invite's link to the invited address.
func (s *Server) sendInvite(ctx context.Context, inv store.Invite) error {
	o, _ := s.store.Org(inv.OrgID)
	link := s.baseURL + "/invites/accept?token=" + url.QueryEscape(inv.Token)
	return s.mail.Send(ctx, mail.Message{
		To:      inv.Email,
		Subject: fmt.Sprintf("You are invited to join %s on Tally", o.Name),
		Body:    fmt.Sprintf("You have been invited to join %s on Tally as %s.\n\nAccept the invitation: %s\n", o.Name, inv.Role, link),
	})
}

func (s *Server) revokeInvite(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	if !auth.CanManageTeam(p.Role) {
		writeError(w, http.StatusForbidden, "forbidden", "only owners and admins manage invites")
		return
